import{_ as a,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"LoadData（BitMode2D矩阵搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_2D_BitMode"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_2D_BitMode.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_2D_BitMode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),l={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_2D_BitMode.md"};function c(d,s,o,i,e,r){return n(),p("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>LoadData（BitMode 2D矩阵搬运）<a id="ZH-CN_TOPIC_0000002517418694"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品 AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品 Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>负责完成普通矩阵计算所需的2D格式数据的搬运，以大小为512字节的数据分形为单位进行搬运，支持的数据通路为：L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer。</p><p>本接口与LoadData（2D矩阵搬运V2）接口的差异在于参数的传入方式不同，本接口传入的是一个联合体结构Load2DBitModeParam。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">TPosition</span><span class="w"> </span><span class="n">Dst</span><span class="p">,</span><span class="w"> </span><span class="n">TPosition</span><span class="w"> </span><span class="n">Src</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadData</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="k">const</span><span class="w"> </span><span class="n">Load2DBitModeParam</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。</td></tr><tr><td>Src</td><td>源操作数存储的逻辑位置（TPosition），支持的取值为A1和B1，仅本接口使用。</td></tr><tr><td>Dst</td><td>目的操作数存储的逻辑位置（TPosition），支持的取值为A2和B2，仅本接口使用。</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下：<br>  • A2：ZZ格式/NZ格式；对应的分形大小为16 * (32字节 / sizeof(T))。<br>  • B2：ZN格式；对应的分形大小为 (32字节 / sizeof(T)) * 16。<br>  • A1/B1：无格式要求，一般情况下为NZ格式。NZ格式下，对应的分形大小为16 * (32字节 / sizeof(T))。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。<br>数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为Load2DBitModeParam，具体参考<a href="#table10539223195311">表3</a>。<br>上述结构体参数定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Load2DBitModeParam类参数说明<a id="table10539223195311"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与Load2DBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>Load2DBitModeConfig0位域（bit-field）结构体类型，参数参考<a href="#table4109172132317">表4</a>，与config0组成联合体（union）。</td></tr><tr><td>config1</td><td>uint64_t类型，与Load2DBitModeConfig1位域（bit-field）结构体类型参数config1BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig1()函数获取其值。</td></tr><tr><td>config1BitMode</td><td>Load2DBitModeConfig1位域（bit-field）结构体类型，参数参考<a href="#table122891852142311">表5</a>，与config1组成联合体（union）。</td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false。含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考<a href="LoadData_2D.html">LoadData（2D矩阵搬运）</a>。<br>  • true：启用<br>  • false：不启用<br>开启转置功能时，支持的数据类型约束如下：<br>源操作数、目的操作数支持b4、b8、b16、b32数据类型。</td></tr></tbody></table><p>Load2DBitModeParam类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>Load2DBitModeParam类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数。</p><p>与使用LoadData2DParamsV2结构体的LoadData接口相比，减少了scalar计算，实现性能提升。</p><p>Load2DBitModeParam类可以直接使用LoadData2DParamsV2结构体类型对象初始化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">LoadData2DParamsV2</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">sid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">ifTranspose</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="n">Load2DBitModeParam</span><span class="w"> </span><span class="nf">params</span><span class="p">(</span><span class="n">loadDataParams</span><span class="p">);</span><span class="w">  </span><span class="c1">// 直接使用LoadData2DParamsV2结构体类型对象初始化</span>
</code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对config0和config1直接进行逐bit位修改来修改参数。</p><p><strong>表 4</strong> Load2DBitModeConfig0结构体参数说明<span id="table4109172132317"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mStartPosition</td><td>以M*K矩阵为例，源矩阵M轴方向的起始位置，单位为16个元素。<br>该参数是位域结构体的最低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetMStartPosition()函数设置其值，使用GetMStartPosition()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr><tr><td>kStartPosition</td><td>以M*K矩阵为例，源矩阵K轴方向的起始位置，单位为32字节。<br>该参数是位域结构体的第二低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetKStartPosition()函数设置其值，使用GetKStartPosition()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr><tr><td>mStep</td><td>以M*K矩阵为例，源矩阵M轴方向搬运长度，单位为16个元素。取值范围：mStep∈[0, 255]。<br>通过ifTranspose参数启用转置功能时，mStep除需满足 [0, 255]的取值范围外，还需满足以下额外约束：<br>  • 当数据类型为b4时，mStep必须是4的倍数；<br>  • 当数据类型为b8时，mStep必须是2的倍数；<br>  • 当数据类型为b16时，mStep必须是1的倍数；<br>  • 当数据类型为b32时，mStep无额外约束。<br>该参数是位域结构体的第三低位参数，占用8bit，可以使用Load2DBitModeParam类对象的SetMStep()函数设置其值，使用GetMStep()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr><tr><td>kStep</td><td>以M*K矩阵为例，源矩阵K轴方向搬运长度，单位为32字节。取值范围：kStep∈[0, 255]。<br>通过ifTranspose参数启用转置功能时，kStep除需满足[0, 255]的取值范围外，还需满足以下额外约束：<br>  • 当数据类型为b4、b8或b16时，kStep没有额外约束；<br>  • 当数据类型为b32时，kStep必须是2的倍数。<br>该参数是位域结构体的最高位参数，占用8bit，可以使用Load2DBitModeParam类对象的SetKStep()函数设置其值，使用GetKStep()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr></tbody></table><p>Load2DBitModeConfig0结构体参数的含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考<a href="LoadData_2D.html">LoadData（2D矩阵搬运）</a>。</p><p><strong>表 5</strong> Load2DBitModeConfig1结构体参数说明<span id="table122891852142311"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>srcStride</td><td>以M*K矩阵为例，源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512字节。<br>该参数是位域结构体的最低位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetSrcStride()函数设置其值，使用GetSrcStride()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr><tr><td>dstStride</td><td>以M*K矩阵为例，目标矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512字节。<br>该参数是位域结构体的最高位参数，占用16bit，可以使用Load2DBitModeParam类对象的SetDstStride()函数设置其值，使用GetDstStride()函数获取其值，具体参考<a href="#table1123714295457">表6</a>。</td></tr></tbody></table><p>Load2DBitModeConfig1结构体参数的含义与LoadData2DParamsV2结构体中的同名参数含义相同，具体参考<a href="LoadData_2D.html">LoadData（2D矩阵搬运）</a>。</p><p><strong>表 6</strong> Load2DBitModeParam类成员函数说明<span id="table1123714295457"></span></p><table><thead><tr><th>函数名称</th><th>功能</th></tr></thead><tbody><tr><td>void SetMStartPosition(uint32_t mStartPosition_)</td><td>将Load2DBitModeConfig0结构体参数mStartPosition的值设置为mStartPosition_。</td></tr><tr><td>void SetKStartPosition(uint32_t kStartPosition_)</td><td>将Load2DBitModeConfig0结构体参数kStartPosition的值设置为kStartPosition_。</td></tr><tr><td>void SetMStep(uint16_t mStep_)</td><td>将Load2DBitModeConfig0结构体参数mStep的值设置为mStep_。</td></tr><tr><td>void SetKStep(uint16_t kStep_)</td><td>将Load2DBitModeConfig0结构体参数kStep的值设置为kStep_。</td></tr><tr><td>void SetSrcStride(int32_t srcStride_)</td><td>将Load2DBitModeConfig1结构体参数srcStride的值设置为srcStride_。</td></tr><tr><td>void SetDstStride(uint16_t dstStride_)</td><td>将Load2DBitModeConfig1结构体参数dstStride的值设置为dstStride_。</td></tr><tr><td>uint32_t GetMStartPosition() const</td><td>获取Load2DBitModeConfig0结构体参数mStartPosition的值。</td></tr><tr><td>uint32_t GetKStartPosition() const</td><td>获取Load2DBitModeConfig0结构体参数kStartPosition的值。</td></tr><tr><td>uint16_t GetMStep() const</td><td>获取Load2DBitModeConfig0结构体参数mStep的值。</td></tr><tr><td>uint16_t GetKStep() const</td><td>获取Load2DBitModeConfig0结构体参数kStep的值。</td></tr><tr><td>int32_t GetSrcStride() const</td><td>获取Load2DBitModeConfig1结构体参数srcStride的值。</td></tr><tr><td>uint16_t GetDstStride() const</td><td>获取Load2DBitModeConfig1结构体参数dstStride的值。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持数据类型为：int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t、int32_t、uint32_t、float。</p><h2 id="返回值说明">返回值说明<a id="section640mcpsimp"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html">通用地址对齐约束</a>。</li></ul><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，仅支持L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据通路。</li></ul></div><h2 id="调用示例">调用示例<a id="section6461234123118"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>完整搬运流程请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/load_data_2dv2_l12l0">LoadData（2D矩阵搬运V2）样例</a>。LoadData（BitMode 2D矩阵搬运）的使用可以参考下面的调用示例，L1上为NZ数据排布、shape为[M,K]的A矩阵，调用LoadData指令完成L1 Buffer-&gt;L0A Buffer的Nz2Nz搬运。</p><ul><li>示例一：使用LoadData2DParamsV2构造Load2DBitModeParam</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">fractalElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tensorElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalElemCount</span><span class="p">;</span>

<span class="c1">// 源操作数：L1 Buffer，存放32x32的half矩阵。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">a1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">tensorElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：L0A Buffer，预留4个512B分形接收完整32x32 half矩阵。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A2</span><span class="p">,</span><span class="w"> </span><span class="n">a2Addr</span><span class="p">,</span><span class="w"> </span><span class="n">tensorElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2DParamsV2</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="c1">// 从源矩阵M轴第0个16元素开始搬运。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 从源矩阵K轴第0个32B开始搬运。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// M方向搬运2 * 16个元素。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// K方向搬运32个half，即2 * 32B。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 源L1的M方向有2个分形，K方向相邻源分形起始地址间隔为2 * 512B。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 目的L0A按2个M方向分形连续排布，K方向相邻目的分形起始地址间隔为2 * 512B。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 不对每个分形做转置，保持L1中的分形方向搬入L0A。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">ifTranspose</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="c1">// 预留参数，固定配置为0。</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">sid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="c1">// 使用LoadData2DParamsV2构造bit mode参数，底层以bit位形式传递上述搬运配置。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Load2DBitModeParam</span><span class="w"> </span><span class="nf">bitModeParams</span><span class="p">(</span><span class="n">loadDataParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A2</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">bitModeParams</span><span class="p">);</span>
</code></pre></div><ul><li>示例二：使用Set函数修改Load2DBitModeParam</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Load2DBitModeParam</span><span class="w"> </span><span class="n">bitModeParams</span><span class="p">;</span>
<span class="c1">// 从源矩阵M轴第0个16元素开始搬运。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetMStartPosition</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="c1">// 从源矩阵K轴第0个32B开始搬运。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetKStartPosition</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="c1">// M方向搬运2 * 16个元素。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetMStep</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="c1">// K方向搬运32个half，即2 * 32B。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetKStep</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="c1">// 源L1的M方向有2个分形，K方向相邻源分形起始地址间隔为2 * 512B。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetSrcStride</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="c1">// 目的L0A按2个M方向分形连续排布，K方向相邻目的分形起始地址间隔为2 * 512B。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetDstStride</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="c1">// 不对每个分形做转置，保持L1中的分形方向搬入L0A。</span>
<span class="n">bitModeParams</span><span class="p">.</span><span class="n">SetIfTranspose</span><span class="p">(</span><span class="nb">false</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A2</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">bitModeParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const b=a(l,[["render",c]]);export{m as __pageData,b as default};
